package com.yeyamo_mobile.api.referral_service.infrastructure.outbox;import java.time.Instant;import java.util.concurrent.TimeUnit;import org.springframework.beans.factory.annotation.Value;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.kafka.core.KafkaTemplate;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;
@Component@ConditionalOnProperty(name="referral.outbox.enabled",havingValue="true",matchIfMissing=true)public class ReferralOutboxPublisher{private final ReferralOutboxRepository repo;private final KafkaTemplate<String,String>kafka;private final String topic;public ReferralOutboxPublisher(ReferralOutboxRepository r,KafkaTemplate<String,String>k,@Value("${yeyamo.kafka.topics.referral-events:referral.events}")String t){repo=r;kafka=k;topic=t;}@Scheduled(fixedDelayString="${referral.outbox.delay-ms:1000}")@Transactional public void publish(){for(var e:repo.findTop100ByPublishedAtIsNullOrderByOccurredAtAsc()){try{kafka.send(topic,e.aggregateId,e.payload).get(5,TimeUnit.SECONDS);e.publishedAt=Instant.now();e.lastError=null;}catch(Exception x){e.attempts++;e.lastError=shorten(x.getMessage());}repo.save(e);}}private String shorten(String s){if(s==null)return"Kafka publication failed";return s.length()>1000?s.substring(0,1000):s;}}
